// Portfolio content. Facts are taken from Behance project data, the project images themselves and Or's CV.
// Image ids refer to src/data/images.json (generated by scripts/images.mjs from the Behance Portfolio folder).

export type Img = { id: string; alt: string };

export type Block =
  | { t: 'full'; img: Img; caption?: string; bleed?: boolean; tone?: string }
  | { t: 'pair'; imgs: [Img, Img]; caption?: string; offset?: boolean }
  | { t: 'grid'; imgs: Img[]; cols?: 2 | 3 | 4; caption?: string }
  | { t: 'text'; label?: string; title?: string; body: string[] }
  | { t: 'split'; img: Img; label?: string; title?: string; body: string[]; side?: 'left' | 'right' }
  | { t: 'chapter'; index: string; title: string; meta: string; body?: string }
  | { t: 'palette'; label: string; body: string; colors: string[] }
  | { t: 'type'; label: string; body: string; lockup: Img; faces: { name: string; role: string; body: string; specimen?: string }[] }
  | { t: 'trio'; label: string; title: string; items: { img: Img; title: string; body: string }[] };

export type Project = {
  slug: string;
  title: string;
  subtitle: string;
  client?: string;
  year: string;
  discipline: string[];
  tools: string[];
  accent: string; // taken from each project's own palette
  cover: Img; // used on the work index and previews
  hero: Img;
  intro: string[];
  behance: string[];
  featured?: boolean;
  blocks: Block[];
};

const i = (id: string, alt: string): Img => ({ id, alt });

